// #241 — INDEXED rotary faces on the exact sweeper (R-4, `/Rotary.md` §2 class I, §4.6).
//
// An indexed job turns the stock to an angle, holds it there, cuts an ordinary 2.5D pass, and
// turns again. This suite is the design's "simulate before the bench" table for the class
// (`docs/design/rotary-flow.md` §6): each fixture is GENERATED by the indexed CAM, POSTED,
// re-PARSED and re-RUN through the timeline (the file is what the machine runs), SWEPT by the
// exact engine, and MATCHED against an analytic oracle that owes nothing to the sweep's code.
//
// THE ORACLES are closed forms of the geometry the mesh really has, not of an ideal circle: a
// Manifold cylinder is an inscribed n-gon, so where the removed region is a thin ring (the hex)
// the polygon's 0.26 % area deficit would read as a 1.5 % volume error — that oracle uses the
// same n-gon's area, and the ideal circle's number is quoted beside it. Each band is stated
// where it is used; a wrong face, sign or depth is orders of magnitude outside all of them.

import { faceKey } from '@/workers/sim/session';
import { rotaryFits, rotaryStockFits } from '@/engine/cnc/setups/plan';
import { describe, it, expect } from 'vitest';
import { tl } from './helpers/manifoldExec';
import { generateIndexed, type IndexedSpec } from '@/engine/cnc/cam/indexed';
import { postZ1, type PostContext } from '@/engine/cnc/post/z1';
import { buildTimeline, parseGcode, stubSetup, Z1, type Setup } from '@/engine/cnc';
import { flatEndMill, type Tool } from '@/engine/cnc/tool';
import { segmentsForRadius } from '@/engine/compiler/arcResolution';
import { sweepTimeline, type SweepResult } from '@/workers/geometry/sweep';
import { verifyProgram } from '@/engine/cnc/verify';
import type { CutParams } from '@/engine/cnc/feeds';

const RADIUS = 10;
const LENGTH = 30;
const STOCK = { kind: 'cylinder' as const, diameter: 2 * RADIUS, length: LENGTH };
const HOLD = { kind: 'rotary-chuck' as const, jawDiameter: 25, stickout: 30 };
const setup = (): Setup => stubSetup(STOCK, HOLD);

const PARAMS: CutParams = { rpm: 12000, feed: 800, plungeFeed: 200, stepDown: 1, stepOver: 1, peck: 1, air: true };
/** A ⌀10 flat: wide enough to cover a 1 mm flat's chord (8.72 mm) and the hex's edge (10 mm) exactly. */
const WIDE: Tool = flatEndMill(10, { shoulderLength: 20, fluteLength: 15 });
/** A ⌀3 flat for the cross-hole; long enough to pass through the 20 mm stock. */
const THIN: Tool = flatEndMill(3, { shoulderLength: 30, fluteLength: 25 });

const ctx = (): PostContext => ({
  jobName: 'indexed fixture',
  stock: { length: LENGTH, width: 2 * RADIUS, thickness: 2 * RADIUS },
  materialName: 'softwood',
  zDatum: 'rotary-axis',
  origin: 'topFrontLeft',
  camVersion: '1.0.0',
  toolKey: 'fixture',
});

/** Area of the circular segment cut by a chord `d` below the surface of a circle of radius R. */
const segmentArea = (R: number, d: number): number => {
  const h = R - d;
  return R * R * Math.acos(h / R) - h * Math.sqrt(R * R - h * h);
};
/** Area of a regular n-gon inscribed in a circle of radius r — the mesh the stock really is. */
const polygonArea = (r: number, n: number): number => (n / 2) * r * r * Math.sin((2 * Math.PI) / n);
const N_STOCK = segmentsForRadius(RADIUS);

/**
 * #729 — a face pass can no longer start inside the jaws: it starts one cutter radius clear of the
 * jaw face (X 0), so the first `capR` mm of the rod are cut only where the cutter's rounded end
 * reaches. The material a face removes there, by numeric integration of the face's depth profile
 * over the disc-covered part of the chord (|y| ≤ halfChord).
 */
function capVolume(capR: number, halfChord: number, depth: (y: number) => number, n = 600): number {
  let v = 0;
  const dx = capR / n;
  for (let i = 0; i < n; i++) {
    const x = (i + 0.5) * dx; // 0 … capR, the pass's centre at x = capR
    const reach = Math.sqrt(Math.max(0, capR * capR - (x - capR) ** 2));
    const half = Math.min(halfChord, reach);
    const dy = (2 * half) / n;
    for (let j = 0; j < n; j++) {
      const y = -half + (j + 0.5) * dy;
      v += Math.max(0, depth(y)) * dx * dy;
    }
  }
  return v;
}
/** The ⌀10 cutter's radius. */
const WIDE_R = 5;
/**
 * The X every face pass now starts at: the cutter's radius plus the verifier's 3 mm jaw keep-out
 * (#729 item 5 — the fixtures go through the verifier too). The rod's first JAW_CLEAR − WIDE_R mm are
 * never reached; the next WIDE_R mm only by the cutter's rounded end.
 */
const JAW_CLEAR = WIDE_R + 3;
/**
 * And every pass ENDS with the cutter's edge at the rod's free end: the verifier refuses a cut that
 * runs off it (#724 B3, `wrap-off-free-end`). The last WIDE_R mm are cut only by the rounded end.
 */
const END_X = LENGTH - WIDE_R;
/** The full-section length a pass covers between its two rounded ends. */
const FULL_SPAN = END_X - JAW_CLEAR;
const STOCK_VOLUME = polygonArea(RADIUS, N_STOCK) * LENGTH;

/** Relative comparison, because every oracle here is a volume in the hundreds of mm³. */
function expectWithin(got: number, want: number, relative: number, what: string): void {
  const err = Math.abs(got - want) / want;
  expect(err, `${what}: ${got.toFixed(4)} against ${want.toFixed(4)} (${(err * 100).toFixed(3)} %)`).toBeLessThan(relative);
}

function dispose(s: SweepResult): void {
  s.stock.delete();
  s.result.delete();
  s.removal?.delete();
  for (const cp of s.perCheckpoint) cp?.delete();
  for (const g of s.gouges) g.solid.delete();
}

/** What ONE run actually took off the blank: its removal solid, trimmed to the stock. */
function removedBy(sweep: SweepResult, k: number): number {
  const solid = sweep.perCheckpoint[k];
  if (!solid) throw new Error(`checkpoint ${k} removed nothing`);
  const cut = solid.intersect(sweep.stock);
  const v = cut.volume();
  cut.delete();
  return v;
}

/**
 * The whole pipeline the acceptance names: generate → post → parse/build (verify) → sweep.
 * Every stage is asserted on the way through rather than only at the end.
 *
 * The POST feeds to the safe height BEFORE the spindle starts (#396's `spindle-at-unknown-z`
 * rule, #240 slice 2), so those opening feeds are not cutting moves and the timeline carries no
 * skipped checkpoint of them: `checkpointsSkipped` is asserted at zero below. (Before that order,
 * the fed move with the spindle already on made one checkpoint above the stock that the sweep
 * skipped — a structural detail of the post's preamble, not a property of the job.)
 */
function runPipeline(spec: IndexedSpec) {
  const ir = generateIndexed(spec);
  expect(ir.frame).toBe('rotary');
  for (const op of ir.operations) for (const m of op.moves) expect(m.a).toBeTypeOf('number');

  const posted = postZ1(ir, ctx(), Z1);
  if (!posted.ok) throw new Error(`the post refused the indexed program: ${posted.errors.join('; ')}`);
  const timeline = buildTimeline(parseGcode(posted.text), setup());
  expect(timeline.diagnostics.filter((d) => d.severity === 'error')).toEqual([]);
  expect(timeline.summary.rotary).toBe(true);
  expect(timeline.summary.rotaryClass).toBe('indexed');

  // #729 item 5 — VERIFY, as #241's own title says (generate → post → verify → sweep).
  const verified = verifyProgram(posted.text, {
    setup: stubSetup(STOCK, HOLD, { startingTool: 1 }, Z1),
    machine: Z1,
    tool: spec.tool,
    depthLimit: () => 0,
    minRapidZ: 1,
    rotary: { radius: RADIUS, stickout: LENGTH, tailstock: false },
  });
  expect(verified.findings.filter((f) => f.severity === 'error').map((f) => `${f.line} ${f.code}`)).toEqual([]);

  const out = sweepTimeline(tl, timeline, spec.tool, setup());
  if (!out.ok) throw new Error(`the sweep refused the indexed program: ${JSON.stringify(out.diagnostics)}`);
  expect(out.value.stats.engine).toBe('exact');
  expect(out.value.stats.checkpointsSkipped).toBe(0);
  expect(out.value.diagnostics.filter((d) => d.severity === 'error')).toEqual([]);
  return { ir, posted, timeline, sweep: out.value };
}

/** The runs that cut the stock — every checkpoint at or below the surface. */
const cuttingRuns = (timeline: { checkpoints: { a: number | null; z: number }[] }) =>
  timeline.checkpoints.filter((cp) => cp.z < RADIUS).map((cp) => ({ a: cp.a, z: cp.z }));

/**
 * The checkpoint index of the (single) run at this A. Derived from the timeline rather than
 * hard-coded: the post's preamble order decides whether an extra non-cutting checkpoint exists
 * (#240 slice 2 feeds to the safe height before the spindle starts, so there is none), and a
 * fixture that indexed absolute checkpoints broke on that change while saying nothing about the
 * job.
 */
const runAt = (timeline: { checkpoints: { a: number | null }[] }, a: number): number => {
  const hits = timeline.checkpoints.flatMap((cp, i) => (cp.a === a ? [i] : []));
  expect(hits.length, `checkpoints at A ${a}`).toBeGreaterThan(0);
  return hits[0]!;
};

describe('#241 the indexed CAM produces a rotary IR the post and the timeline agree on', () => {
  it('cuts a face in constant-Z levels, shallowest first, A held on every move', () => {
    const ir = generateIndexed({
      radius: RADIUS,
      faces: [{ a: 0, fromX: 0, toX: 10, depth: 1 }],
      tool: WIDE,
      params: { ...PARAMS, stepDown: 0.5 },
      rapid: Z1.rapidEstimate,
    });
    expect(ir.frame).toBe('rotary');
    expect(ir.rotary).toEqual({ radius: RADIUS });
    const moves = ir.operations[0]!.moves;
    // The two levels are the only distinct cutting Zs, and they are cut shallowest first.
    const cutZs = [...new Set(moves.filter((m) => m.kind === 'feed').map((m) => m.z))];
    expect(cutZs).toEqual([RADIUS - 0.5, RADIUS - 1]);
    expect(new Set(moves.map((m) => m.a))).toEqual(new Set([0]));
    expect(moves.every((m) => m.y === 0)).toBe(true);
  });

  it('refuses what the machine would refuse: a cone, an empty span, a zero depth, an empty job', () => {
    const base = { radius: RADIUS, tool: WIDE, params: PARAMS, rapid: Z1.rapidEstimate };
    expect(() =>
      generateIndexed({ ...base, tool: flatEndMill(10, { shape: 'engraving', halfAngle: 30 }), faces: [{ a: 0, fromX: 0, toX: 10, depth: 1 }] }),
    ).toThrow(/flat end mill only/);
    expect(() => generateIndexed({ ...base, faces: [{ a: 0, fromX: 5, toX: 5, depth: 1 }] })).toThrow(/empty X span/);
    expect(() => generateIndexed({ ...base, faces: [{ a: 0, fromX: 0, toX: 10, depth: 0 }] })).toThrow(/positive depth/);
    expect(() => generateIndexed({ ...base })).toThrow(/nothing to cut/);
  });
});

describe('#241 fixture: TWO FLATS, 0° and 180°, 1 mm deep on ⌀20 (rotary-flow §6)', () => {
  const spec: IndexedSpec = {
    radius: RADIUS,
    faces: [
      // #729 — clear of the jaws (X 0 is the jaw face): a pass from X −5 drove the cutter into the
      // chuck, which the sweep now refuses.
      { a: 0, fromX: JAW_CLEAR, toX: END_X, depth: 1 },
      { a: 180, fromX: JAW_CLEAR, toX: END_X, depth: 1 },
    ],
    tool: WIDE,
    params: PARAMS,
    rapid: Z1.rapidEstimate,
  };

  it('generates, verifies, simulates exactly, and matches the chord segment per face', () => {
    const { timeline, sweep } = runPipeline(spec);

    // The runs split on A: one checkpoint per face, both at the same Z (R4) — two faces at the
    // same depth cannot fold into one solid.
    expect(cuttingRuns(timeline)).toEqual([
      { a: 0, z: RADIUS - 1 },
      { a: 180, z: RADIUS - 1 },
    ]);
    expect(sweep.stats.checkpointsSwept).toBe(2);

    // THE ORACLE: the chord segment of the ideal circle, per face. The band covers the stock's
    // inscribed n-gon (chord error 0.005 mm over an 8.72 mm chord is 0.029 mm² against the
    // segment's 5.87 — about 0.5 %), which is the only approximation in the geometry: the pass's
    // rectangle is exact and lies wholly inside the chord.
    const halfChord = Math.sqrt(RADIUS * RADIUS - (RADIUS - 1) ** 2);
    const perFace =
      segmentArea(RADIUS, 1) * FULL_SPAN +
      2 * capVolume(WIDE_R, halfChord, (y) => Math.sqrt(RADIUS * RADIUS - y * y) - (RADIUS - 1));
    expectWithin(removedBy(sweep, runAt(timeline, 0)), perFace, 0.01, 'face 0');
    expectWithin(removedBy(sweep, runAt(timeline, 180)), perFace, 0.01, 'face 180');
    expectWithin(sweep.stats.removedVolume, 2 * perFace, 0.01, 'both faces');
    // The accounting is the sweep's own and must close exactly.
    expect(sweep.stats.resultVolume).toBeCloseTo(sweep.stats.stockVolume - sweep.stats.removedVolume, 6);
    expectWithin(sweep.stats.stockVolume, STOCK_VOLUME, 0.0001, 'stock');
    // Nothing else was touched: the flats cut two caps off the top, so the result's highest
    // point is the flat floor — a turned-down cylinder would sit lower at the sides.
    // #729 — except within the jaw clearance, where the cutter's rounded end leaves the chord's
    // corners at full height: the uncut rod there still reaches the radius.
    expect(sweep.result.boundingBox().max[2]).toBeCloseTo(RADIUS, 3);
    dispose(sweep);
  });
});

describe('#241 fixture: HEX ALL ROUND, six faces, across flats 17.321 on ⌀20 (rotary-flow §6)', () => {
  const APOTHEM = RADIUS * Math.cos(Math.PI / 6); // 8.660 — across flats 17.321
  const DEPTH = RADIUS - APOTHEM;
  const spec: IndexedSpec = {
    radius: RADIUS,
    // #729 — every pass starts clear of the jaws (see the two-flats fixture).
    faces: [0, 60, 120, 180, 240, 300].map((a) => ({ a, fromX: JAW_CLEAR, toX: END_X, depth: DEPTH })),
    tool: WIDE,
    params: { ...PARAMS, stepDown: DEPTH },
    rapid: Z1.rapidEstimate,
  };

  it('cuts six runs at the apothem and leaves the inscribed hexagon', () => {
    const { timeline, sweep } = runPipeline(spec);
    const runs = cuttingRuns(timeline);
    expect(runs.map((r) => r.a)).toEqual([0, 60, 120, 180, 240, 300]);
    // The posted file carries 3 decimals (Z8.66), so the simulated face is at 8.66, not the
    // ideal apothem 8.660254 — a 0.00025 mm deeper cut, and inside every band below.
    for (const r of runs) expect(r.z).toBeCloseTo(APOTHEM, 3);
    expect(sweep.stats.checkpointsSwept).toBe(6);

    // THE ORACLE: "the hexagon's area at every X" (rotary-flow §6). The removed volume is the
    // stock's own n-gon minus the hexagon inscribed in the same circle: 54.15 mm² per length
    // against the ideal circle's πR² − (3√3/2)R² = 54.35. The hexagon's corners cost a further
    // ~0.00002 mm² each (the n-gon cuts them by its chord error), below the 0.5 % band here.
    const hexArea = 2 * Math.sqrt(3) * APOTHEM * APOTHEM;
    // #729 — past the jaw clearance the section is the full ring; in the first JAW_CLEAR mm each
    // face removes only what the cutter's rounded end reaches of its segment (|y| ≤ R/2 per face).
    const ringArea = polygonArea(RADIUS, N_STOCK) - hexArea;
    const facecap = capVolume(WIDE_R, RADIUS / 2, (y) => Math.sqrt(RADIUS * RADIUS - y * y) - APOTHEM);
    const ring = ringArea * FULL_SPAN + 12 * facecap;
    expectWithin(sweep.stats.removedVolume, ring, 0.005, 'hex ring');
    // Each face's own removal is its share: one sixth, give or take where the neighbouring faces'
    // segments reach past the shared hexagon vertex.
    for (let k = 0; k < 6; k++) expectWithin(removedBy(sweep, runAt(timeline, k * 60)), ring / 6, 0.02, `face ${k}`);
    // The remaining solid, derived independently: the hexagon past the clearance, the rod's own
    // n-gon within it, less what the six caps took there.
    expectWithin(
      sweep.stats.resultVolume,
      hexArea * FULL_SPAN + polygonArea(RADIUS, N_STOCK) * (LENGTH - FULL_SPAN) - 12 * facecap,
      0.005,
      'hexagon solid',
    );
    dispose(sweep);
  });
});

describe('#241 fixture: CROSS-HOLE, ⌀3 through at 90° (rotary-flow §6)', () => {
  const HOLE_R = 1.5;
  const spec: IndexedSpec = {
    radius: RADIUS,
    holes: [{ a: 90, x: LENGTH / 2, depth: 2 * RADIUS + 2 }],
    tool: THIN,
    params: PARAMS,
    rapid: Z1.rapidEstimate,
  };

  it('plunges past the far side at the index and removes the hole cylinder', () => {
    const { timeline, sweep } = runPipeline(spec);
    expect(cuttingRuns(timeline)).toEqual([{ a: 90, z: -RADIUS - 2 }]);
    expect(sweep.stats.checkpointsSwept).toBe(1);

    // THE ORACLE: the hole's cross-section — the ⌀3 cutter's own inscribed polygon, less what
    // the region's `simplify` pass drops — times the stock's diameter. The stock's own n-gon
    // changes the hole's LENGTH by its chord error, 0.01 mm in 20: 0.05 %.
    const holeArea = polygonArea(HOLE_R, segmentsForRadius(HOLE_R));
    const want = holeArea * 2 * RADIUS;
    expectWithin(removedBy(sweep, runAt(timeline, 90)), want, 0.005, 'hole');
    expectWithin(sweep.stats.removedVolume, want, 0.005, 'hole (stats)');
    expect(sweep.stats.resultVolume).toBeCloseTo(sweep.stats.stockVolume - sweep.stats.removedVolume, 6);
    dispose(sweep);
  });
});

describe('#241 the air gate on an indexed job', () => {
  it('refuses a turn taken with the tool down, even between two faces it has already cut', () => {
    // The tool sits in the 0° groove at Z 9 (both END positions of the turn are clear — they are
    // in cuts already made) and A turns to 180°: the sector between sweeps untouched material at
    // A 90°. The two end positions cannot see that, so the move is refused by name.
    const src = [
      'S1000 M3',
      'G0 X5 Y0 Z15 A0',
      'G1 Z9 F200',
      'G1 X35 F800',
      'G0 Z15',
      'G0 A180',
      'G1 Z9 F200',
      'G1 X5 F800',
      'G0 Z15 A0',
      'G0 X15 Y0',
      'G0 Z9',
      'G0 A180',
      'G0 Z15',
    ].join('\n');
    const timeline = buildTimeline(parseGcode(src), setup());
    expect(timeline.summary.rotaryClass).toBe('indexed');
    const out = sweepTimeline(tl, timeline, WIDE, setup());
    if (!out.ok) throw new Error(JSON.stringify(out.diagnostics));
    // #729 — the case this test names is LINE 12 (the turn with the tool down in the groove). Line
    // 9's retract-while-turning starts in the groove too and is refused as well; pin each by line.
    const turns = out.value.diagnostics.filter((d) => d.code === 'rotary-turn-in-stock');
    expect(turns.find((d) => d.message.startsWith('line 12:'))?.severity).toBe('error');
    expect(turns.find((d) => d.message.startsWith('line 12:'))?.message).toMatch(/index turn/);
    expect(turns.some((d) => d.message.startsWith('line 9:'))).toBe(true);
    dispose(out.value);
  });

  it('#729 — clears a lift-and-turn with the cutter wholly past the rod’s free end', () => {
    // The rod is X 0 → 30; the ⌀10 cutter at X 36 is clear of it by 1 mm, so a turn at Z 9 sweeps
    // nothing of the ROD even though it is below the rod's top. That is where a tailstock sits, and
    // #723 R-4 review moved the fact out of the diagnostics: a `fixture-unchecked` info on every
    // rotary job could not discriminate, so the RESULT states it once (the coverage bands) and the
    // sweep raises no such info at all.
    const src = ['S1000 M3', 'G0 X36 Y0 Z15 A0', 'G0 Z9', 'G0 A90', 'G0 Z15'].join('\n');
    const timeline = buildTimeline(parseGcode(src), setup());
    const out = sweepTimeline(tl, timeline, WIDE, setup());
    if (!out.ok) throw new Error(JSON.stringify(out.diagnostics));
    expect(out.value.diagnostics.some((d) => d.code === 'rotary-turn-in-stock')).toBe(false);
    expect(out.value.diagnostics.some((d) => d.code === 'fixture-unchecked')).toBe(false);
    dispose(out.value);
  });

  it('clears a turn taken above the stock at the safe height', () => {
    const src = ['S1000 M3', 'G0 X15 Y0 Z15 A0', 'G1 Z9 F100', 'G0 Z15', 'G0 A90', 'G1 Z9 F100', 'G0 Z15'].join('\n');
    const timeline = buildTimeline(parseGcode(src), setup());
    expect(timeline.summary.rotaryClass).toBe('indexed');
    const out = sweepTimeline(tl, timeline, WIDE, setup());
    if (!out.ok) throw new Error(JSON.stringify(out.diagnostics));
    expect(out.value.diagnostics.filter((d) => d.severity === 'error')).toEqual([]);
    dispose(out.value);
  });
});

describe('#729 — the retroactive review: the chuck, an unstated A, and face matching', () => {
  it('refuses a rapid into the jaws: a pure-Z rapid at X −10 down to Z −5', () => {
    const src = ['S1000 M3', 'G0 X15 Y0 Z15 A0', 'G0 X-10', 'G0 Z-5', 'G0 Z15'].join('\n');
    const timeline = buildTimeline(parseGcode(src), setup());
    const out = sweepTimeline(tl, timeline, WIDE, setup());
    const diags = out.ok ? out.value.diagnostics : out.diagnostics;
    const chuck = diags.find((d) => d.code === 'rotary-into-chuck');
    expect(chuck?.severity).toBe('error');
    // Line 3 moves over the chuck at Z 15, above the jaws' reach (12.5): clear. Line 4 drops into them.
    expect(chuck?.message).toContain('line 4: a rapid reaches the chuck');
    if (out.ok) dispose(out.value);
  });

  it('refuses a cut that reaches past the jaw face below the rod top, with no per-job fixture info', () => {
    // A ⌀10 pass starting at X 2: its edge is at X −3, inside the jaws, 1 mm below the top.
    const src = ['S1000 M3', 'G0 X2 Y0 Z15 A0', 'G1 Z9 F100', 'G1 X20', 'G0 Z15'].join('\n');
    const timeline = buildTimeline(parseGcode(src), setup());
    const out = sweepTimeline(tl, timeline, WIDE, setup());
    if (!out.ok) throw new Error(JSON.stringify(out.diagnostics));
    expect(out.value.diagnostics.find((d) => d.code === 'rotary-into-chuck')?.message).toContain('line 3: a cut reaches the chuck');
    // #723 R-4 review: the jaws' own refusal stays; the "tailstock unchecked" INFO left the
    // diagnostics for the result's coverage sentence, so nothing fires on every rotary job.
    expect(out.value.diagnostics.some((d) => d.code === 'fixture-unchecked')).toBe(false);
    dispose(out.value);
  });

  it('refuses a rapid that crosses the jaw zone between two clear ends (D1)', () => {
    // From above-and-beyond the jaws down to beside the rod: both ends are clear, the line is not.
    const src = ['S1000 M3', 'G0 X-10 Y20 Z14 A0', 'G0 X5 Y20 Z5', 'G0 Z15'].join('\n');
    const timeline = buildTimeline(parseGcode(src), setup());
    const out = sweepTimeline(tl, timeline, WIDE, setup());
    const diags = out.ok ? out.value.diagnostics : out.diagnostics;
    expect(diags.find((d) => d.code === 'rotary-into-chuck')?.severity).toBe('error');
    if (out.ok) dispose(out.value);
  });

  it('refuses a move over the jaws above the rod top but below the jaws’ reach (D2)', () => {
    // The fixture's jaws are ⌀25 (reach 12.5) on a ⌀20 rod (top 10): Z 12 is above the rod, in the jaws.
    const src = ['S1000 M3', 'G0 X15 Y0 Z15 A0', 'G0 X-10 Z12', 'G0 Z15'].join('\n');
    const timeline = buildTimeline(parseGcode(src), setup());
    const out = sweepTimeline(tl, timeline, WIDE, setup());
    const diags = out.ok ? out.value.diagnostics : out.diagnostics;
    expect(diags.find((d) => d.code === 'rotary-into-chuck')?.message).toContain('below Z 12.500 mm');
    if (out.ok) dispose(out.value);
    // Above the jaws it is clear.
    const high = buildTimeline(parseGcode(['S1000 M3', 'G0 X15 Y0 Z15 A0', 'G0 X-10 Z15', 'G0 X15'].join('\n')), setup());
    const ok = sweepTimeline(tl, high, WIDE, setup());
    if (!ok.ok) throw new Error(JSON.stringify(ok.diagnostics));
    expect(ok.value.diagnostics.some((d) => d.code === 'rotary-into-chuck')).toBe(false);
    dispose(ok.value);
  });

  it('a pass one cutter radius clear of the jaws is not refused', () => {
    const src = ['S1000 M3', 'G0 X5 Y0 Z15 A0', 'G1 Z9 F100', 'G1 X20', 'G0 Z15'].join('\n');
    const timeline = buildTimeline(parseGcode(src), setup());
    const out = sweepTimeline(tl, timeline, WIDE, setup());
    if (!out.ok) throw new Error(JSON.stringify(out.diagnostics));
    expect(out.value.diagnostics.some((d) => d.code === 'rotary-into-chuck')).toBe(false);
    dispose(out.value);
  });

  it('refuses a rotary program that cuts before it ever states A', () => {
    const src = ['S1000 M3', 'G0 X15 Y0 Z15', 'G1 Z9 F100', 'G0 Z15', 'G0 A90', 'G1 Z9 F100', 'G0 Z15'].join('\n');
    const timeline = buildTimeline(parseGcode(src), setup());
    const before = timeline.diagnostics.find((d) => d.code === 'rotary-cut-before-a');
    expect(before?.severity).toBe('error');
    expect(before?.line).toBe(3);
    // A feed ABOVE the rod before A (a vendor file's opening `G01 Z30`) engages no face: not refused.
    const air = buildTimeline(parseGcode(['S1000 M3', 'G01 Z30 F1500', 'G0 X15 Y0 Z15 A0', 'G1 Z9 F100', 'G0 Z15'].join('\n')), setup());
    expect(air.diagnostics.some((d) => d.code === 'rotary-cut-before-a')).toBe(false);
    // A flat program that never states A is not touched by the rule.
    const flat = buildTimeline(parseGcode(['S1000 M3', 'G0 X15 Y0 Z15', 'G1 Z9 F100', 'G0 Z15'].join('\n')), setup());
    expect(flat.diagnostics.some((d) => d.code === 'rotary-cut-before-a')).toBe(false);
  });

  it('names one face however the angle is written: 0/360, −90/270, and the post’s 3 decimals', () => {
    expect(faceKey(360)).toBe(0);
    expect(faceKey(0)).toBe(0);
    expect(faceKey(-90)).toBe(270);
    expect(faceKey(720 + 45)).toBe(45);
    expect(faceKey(360 / 7)).toBe(faceKey(51.429));
    expect(faceKey(null)).toBe(0);
  });
});

describe('#729 — a round stock fits the rotary by its own diameter', () => {
  const ENV = { diameter: 80, length: 150 };
  it('a ⌀60 × 100 rod fits ⌀80 (its box diagonal, ⌀85, would not)', () => {
    expect(rotaryStockFits({ length: 100, width: 60, thickness: 60 }, true, ENV)).toBe(true);
    expect(rotaryFits({ x: 100, y: 60, z: 60 }, ENV)).toBe(false);
    // Standing (D × D × L) reads the same.
    expect(rotaryStockFits({ length: 60, width: 60, thickness: 100 }, true, ENV)).toBe(true);
    // Too fat or too long is still refused; a block keeps the diagonal rule.
    expect(rotaryStockFits({ length: 100, width: 82, thickness: 82 }, true, ENV)).toBe(false);
    expect(rotaryStockFits({ length: 160, width: 60, thickness: 60 }, true, ENV)).toBe(false);
    expect(rotaryStockFits({ length: 100, width: 60, thickness: 60 }, false, ENV)).toBe(false);
  });
});
